import type {AgentRun} from "@/domain/agent";
import type {AgentImageReference, AgentSelectedReferences} from "@/domain/referenceInput";
import {useEffect, useRef, useState} from "react";
import {useProductQuery} from "@/lib/storage/hooks";
import {FileText, ImageIcon, Paperclip, X} from "lucide-react";
import {binaryPreviewMessage, useBinaryPreview} from "@/lib/media";
import {getReferenceSource} from "@/db/references";
import {type ProjectReference, type ReferenceAttachment, referenceLocatorLabel} from "@/domain/references";
import {Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle} from "@/components/ui/dialog";
import "./references.css";

export const REFERENCE_STATUS_LABELS: Record<ProjectReference["status"], string> = {
    parsing: "解析中",
    ready: "可使用",
    partial: "部分解析",
    failed: "解析失败",
    unavailable: "已移除"
};

function ReferenceIcon({kind}: { kind?: string }) {
    return kind === "image" ? <ImageIcon size={16} aria-hidden/> : <FileText size={16} aria-hidden/>;
}

function SourcePreview({projectId, attachment, chunkIndex}: {
    projectId: string;
    attachment: ReferenceAttachment;
    chunkIndex?: number
}) {
    const [attempt, setAttempt] = useState(0);
    const key = `${projectId}/${attachment.referenceId}/${attachment.revision}`;
    const loaded = useProductQuery(async (db) => {
        try {
            return {key, data: await getReferenceSource(projectId, attachment, db), error: undefined};
        } catch (error) {
            return {key, data: undefined, error: error instanceof Error ? error.message : "读取资料失败"};
        }
    }, [key, attempt]);
    const result = loaded?.key === key ? loaded : undefined;
    const source = result?.data;
    const image = useBinaryPreview(source?.reference.kind === "image" ? source.media.blob : undefined);
    const [visible, setVisible] = useState(Math.max(20, (chunkIndex ?? 0) + 1));
    const targetRef = useRef<HTMLElement>(null);
    useEffect(() => {
        if (source && chunkIndex !== undefined) targetRef.current?.scrollIntoView({block: "center"});
    }, [source, chunkIndex]);
    if (!result) return <p role="status">正在读取资料…</p>;
    if (!source) return <div className="reference-error" role="alert"><p>{result.error}</p>
        <button type="button" onClick={() => setAttempt((n) => n + 1)}>重新读取</button>
        <p>历史消息中的引用会保留；不可用的资料无法参与新的请求。</p></div>;
    const {reference, chunks} = source;
    return <>
        <div className="reference-source-meta"><ReferenceIcon
            kind={reference.kind}/><strong>{reference.filename}</strong><span>v{reference.revision} · {REFERENCE_STATUS_LABELS[reference.status]}</span>
        </div>
        <p className="reference-note">{reference.kind === "image" ? "原始图片 · 发送后由所选模型读取" : `已提取 ${reference.coverage.characters.toLocaleString()} 字符 · 处理 ${reference.coverage.processedUnits}/${reference.coverage.totalUnits} 个来源单元。这里是提取预览，不代表模型已完整阅读。`}</p>
        {reference.warnings.map((warning, i) => <p className="reference-warning" key={i}>{warning}</p>)}
        {reference.coverage.emptyUnits.length > 0 &&
            <p className="reference-warning">没有可提取文字的单元：{reference.coverage.emptyUnits.join("、")}</p>}
        <div className="reference-preview">
            {reference.kind === "image" ? image.status === "ready" ? <img src={image.url} onError={image.onError} alt={reference.filename}/> : <p role="status">{binaryPreviewMessage(image)}</p> : chunks.length ? <>{chunks.slice(0, visible).map((chunk) =>
                    <section key={chunk.id} ref={chunk.index === chunkIndex ? targetRef : undefined}
                             className={chunk.index === chunkIndex ? "reference-cited-chunk" : undefined}><span
                        className="reference-locator">{referenceLocatorLabel(chunk.locator)} · 片段 {chunk.index + 1}</span>
                        <pre>{chunk.text}</pre>
                    </section>)}{visible < chunks.length && <button type="button"
                                                                    onClick={() => setVisible((n) => n + 20)}>继续查看（还有 {chunks.length - visible} 段）</button>}</> :
                <p>文件中没有提取到文字。</p>}
        </div>
    </>;
}

export function ReferenceSourceLink({projectId, attachment, label, chunkIndex}: {
    projectId: string;
    attachment: ReferenceAttachment;
    label?: string;
    chunkIndex?: number
}) {
    const [open, setOpen] = useState(false);
    const loaded = useProductQuery(async (db) => {
        try {
            return {
                projectId,
                id: attachment.referenceId,
                row: await db.projectReferences.get(attachment.referenceId) ?? null
            };
        } catch {
            return {projectId, id: attachment.referenceId, row: null};
        }
    }, [projectId, attachment.referenceId]);
    const row = loaded?.projectId === projectId && loaded.id === attachment.referenceId && loaded.row?.projectId === projectId ? loaded.row : undefined;
    return <>
        <button type="button" className="reference-source-link" onClick={() => setOpen(true)}
                title={row?.filename ?? label}><ReferenceIcon
            kind={row?.kind}/><span>{label ?? row?.filename ?? "参考资料"}</span>{row?.status === "unavailable" &&
            <small>已移除</small>}</button>
        <Dialog open={open} onOpenChange={setOpen}><DialogContent
            className="reference-dialog"><DialogHeader><DialogTitle>来源资料</DialogTitle><DialogDescription>原始内容与提取结果
            · 只在发送或工具读取时分享给模型</DialogDescription></DialogHeader>{open &&
            <SourcePreview key={`${projectId}/${attachment.referenceId}/${attachment.revision}`} projectId={projectId}
                           attachment={attachment} chunkIndex={chunkIndex}/>}</DialogContent></Dialog></>;
}

export function ReferenceAttachments({projectId, attachments, onRemove}: {
    projectId?: string;
    attachments: ReferenceAttachment[];
    onRemove?: (attachment: ReferenceAttachment) => void
}) {
    if (!attachments.length) return null;
    return <div className="reference-chips" aria-label="已附加的资料">{attachments.map((attachment) => <span
        className="reference-chip" key={`${attachment.referenceId}/${attachment.revision}`}>{projectId ?
        <ReferenceSourceLink projectId={projectId} attachment={attachment}/> : <><Paperclip
            size={14}/>参考资料</>}{onRemove &&
        <button type="button" aria-label="从消息中移除附件" title="仅从草稿中移除，项目资料仍保留"
                onClick={() => onRemove(attachment)}><X size={14}/></button>}</span>)}</div>;
}

export function ReferenceMessageSources({context, run, content}: {
    context?: AgentSelectedReferences;
    run?: AgentRun;
    content: string
}) {
    const audits = run?.referenceAudit ?? [];
    const inputs = [...(context ? [context] : []), ...audits.flatMap((audit) => audit.inputs)];
    const citations = [...content.matchAll(/(ref_[a-zA-Z0-9-]+)@(\d+)#(\d+)/g)].flatMap((match) => {
        const referenceId = match[1];
        const revision = Number(match[2]);
        const chunkIndex = Number(match[3]);
        const input = inputs.find((input) => input.references.some((item) => item.referenceId === referenceId && item.revision === revision));
        return input ? [{projectId: input.projectId, referenceId, revision, chunkIndex}] : [];
    }).filter((item, i, all) => all.findIndex((other) => other.projectId === item.projectId && other.referenceId === item.referenceId && other.revision === item.revision && other.chunkIndex === item.chunkIndex) === i);
    if (!inputs.length) return null;
    return <div className="reference-message-sources">{context &&
        <ReferenceAttachments projectId={context.projectId} attachments={context.references}/>}{citations.length > 0 &&
        <div className="reference-chips">{citations.map((citation) => <ReferenceSourceLink
            key={`${citation.referenceId}/${citation.revision}/${citation.chunkIndex}`} projectId={citation.projectId}
            attachment={citation} chunkIndex={citation.chunkIndex}
            label={`引用 · 片段 ${citation.chunkIndex + 1}`}/>)}</div>}{audits.length > 0 && <details>
        <summary>请求资料记录 · {audits.length} 次请求</summary>
        {audits.map((audit) => <section key={audit.step}>
            <strong>第 {audit.step} 次请求</strong>{audit.inputs.map((input, index) => <div key={index}>
            <ReferenceAttachments projectId={input.projectId}
                                  attachments={input.references}/>{input.images?.filter((image) => !image.reference).map((image) =>
            <ProjectImageSource key={image.mediaId} image={image}/>)}{input.coverage?.map((coverage) => <p
            className="reference-note"
            key={`${coverage.referenceId}/${coverage.revision}`}>{coverage.filename} · {coverage.kind === "image" ? input.images?.some((image) => image.reference?.referenceId === coverage.referenceId && image.reference.revision === coverage.revision) ? "本轮图片输入（图像 token 为估算）" : "图片来源记录（本轮不含图片像素）" : `包含 ${coverage.includedChunkIndices.length}/${coverage.totalChunks} 段，${coverage.includedCharacters.toLocaleString()} 字符${coverage.partial ? " · 部分内容" : ""}`}{coverage.warnings.length > 0 ? ` · ${coverage.warnings.join("；")}` : ""}</p>)}
        </div>)}</section>)}</details>}</div>;
}

function ProjectImageSource({image}: { image: AgentImageReference }) {
    const [open, setOpen] = useState(false);
    const key = `${image.projectId}/${image.mediaId}`;
    const loaded = useProductQuery(async (db) => {
        try {
            const media = open && await db.projects.get(image.projectId) ? await db.media.get(image.mediaId) : undefined;
            return {
                key,
                media: media?.projectId === image.projectId && ["image/png", "image/jpeg", "image/webp"].includes(media.mimeType) ? media : null
            };
        } catch {
            return {key, media: null};
        }
    }, [key, open]);
    const media = loaded?.key === key ? loaded.media : undefined;
    const preview = useBinaryPreview(media?.blob);
    return <>
        <button className="reference-source-link" type="button" onClick={() => setOpen(true)}><ImageIcon
            size={14}/><span>{image.filename} · 本轮图片输入</span></button>
        <Dialog open={open} onOpenChange={setOpen}><DialogContent
            className="reference-dialog"><DialogHeader><DialogTitle>{image.filename}</DialogTitle><DialogDescription>为本次请求准备的项目图片；不代表请求已经发出。图像
            token 用量为估算。</DialogDescription></DialogHeader>
            <div className="reference-preview">{media === undefined ? <p>加载中…</p> : !media ?
                <p>原始图片已不可用，历史引用记录仍保留。</p> : preview.status === "ready" ? <img src={preview.url} onError={preview.onError} alt={image.filename}/> : <p role="status">{binaryPreviewMessage(preview)}</p>}</div>
        </DialogContent></Dialog></>;
}

import {binaryPreviewMessage, useBinaryPreview} from "@/lib/media";
import type {MediaRecord} from "@/domain/types";
import {useState} from "react";
import {useProductQuery} from "@/lib/storage/hooks";
import {Check, Plus, RotateCcw, Search, Trash2, Upload} from "lucide-react";
import {toast} from "sonner";
import {listProjectReferences, removeProjectReference} from "@/db/references";
import {registerProjectImage, retryReferenceImport} from "@/lib/references/import";
import {type ProjectReference, type ReferenceAttachment, referenceAttachment} from "@/domain/references";
import {Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle} from "@/components/ui/dialog";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle
} from "@/components/ui/alert-dialog";
import {REFERENCE_STATUS_LABELS, ReferenceSourceLink} from "./ReferenceAttachments";

export function ReferenceLibrary({projectId, open, onOpenChange, selected, onSelect, onImport}: {
    projectId: string;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    selected: ReferenceAttachment[];
    onSelect: (attachment: ReferenceAttachment) => void;
    onImport: () => void
}) {
    const [view, setView] = useState<"references" | "images">("references");
    const [query, setQuery] = useState("");
    const [attempt, setAttempt] = useState(0);
    const [busy, setBusy] = useState<string>();
    const [remove, setRemove] = useState<ProjectReference>();
    const loaded = useProductQuery(async (db) => {
        try {
            return {projectId, rows: open ? await listProjectReferences(projectId, db) : [], error: undefined};
        } catch (error) {
            return {projectId, rows: [], error: error instanceof Error ? error.message : "读取资料库失败"};
        }
    }, [projectId, open, attempt]);
    const loadedImages = useProductQuery(async (db) => {
        try {
            return {
                projectId,
                rows: open && view === "images" ? await db.media.where("projectId").equals(projectId).filter((row) => ["image/png", "image/jpeg", "image/webp"].includes(row.mimeType)).toArray() : [],
                error: undefined
            };
        } catch {
            return {projectId, rows: [], error: "读取项目图片失败，请重新打开资料库"};
        }
    }, [projectId, open, view]);
    const images = loadedImages?.projectId === projectId ? loadedImages : undefined;

    async function chooseImage(media: MediaRecord) {
        if (busy) return;
        setBusy(media.id);
        try {
            const reference = await registerProjectImage(projectId, media.id);
            if (reference.status !== "ready") throw new Error(reference.error ?? "图片不可用");
            onSelect(referenceAttachment(reference));
            toast.success("已附加到消息");
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "附加图片失败");
        } finally {
            setBusy(undefined);
        }
    }

    const result = loaded?.projectId === projectId ? loaded : undefined;
    const rows = result?.rows.filter((row) => row.filename.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())) ?? [];

    async function retry(row: ProjectReference) {
        setBusy(row.id);
        try {
            await retryReferenceImport(projectId, row.id);
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "重新解析失败");
        } finally {
            setBusy(undefined);
        }
    }

    async function removeSource() {
        if (!remove || busy) return;
        setBusy(remove.id);
        try {
            await removeProjectReference(projectId, remove.id);
            setRemove(undefined);
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "移除失败");
        } finally {
            setBusy(undefined);
        }
    }

    return <><Dialog open={open} onOpenChange={onOpenChange}><DialogContent
        className="reference-dialog"><DialogHeader><DialogTitle>项目资料</DialogTitle><DialogDescription>此项目的对话共享资料库。只将你选择的资料附加到当前消息。</DialogDescription></DialogHeader>
        <div className="reference-library-tabs" aria-label="资料类型">
            <button type="button" aria-pressed={view === "references"} onClick={() => setView("references")}>参考资料
            </button>
            <button type="button" aria-pressed={view === "images"} onClick={() => setView("images")}>项目图片</button>
        </div>
        <div className="reference-library-toolbar"><label><Search size={16}/><input autoFocus aria-label="搜索项目资料"
                                                                                    placeholder="搜索文件名…"
                                                                                    value={query}
                                                                                    onChange={(e) => setQuery(e.target.value)}/></label>
            <button type="button" onClick={onImport}><Upload size={16}/>导入</button>
        </div>
        <p className="reference-note">图片 ≤10 MB · TXT / MD ≤5 MB · PDF / DOCX ≤20 MB · 每次最多 10 个</p>
        <div className="reference-library-list">
            {view === "images" ? !images ? <p role="status">加载图片…</p> : images.error ?
                <p role="alert">{images.error}</p> : <><p
                    className="reference-note">包括上传和生成的图片。点击附加可让当前模型查看原始图片。</p>
                    <div
                        className="reference-image-grid">{images.rows.filter((row) => row.filename.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())).map((media) =>
                        <ProjectImage key={media.id} media={media} disabled={!!busy}
                                      onSelect={() => void chooseImage(media)}/>)}</div>
                    {!images.rows.length && <p className="reference-empty">项目中还没有图片</p>}</> : !result ?
                <p role="status">加载中…</p> : result.error ? <div role="alert"><p>{result.error}</p>
                    <button type="button" onClick={() => setAttempt((n) => n + 1)}>重试</button>
                </div> : !rows.length ? <div className="reference-empty"><Upload
                    size={28}/><strong>{query ? "没有匹配的资料" : "把创作参考放在这里"}</strong>
                    <p>导入剧本、文档或图片，之后可以在项目的其他对话中复用。</p></div> : rows.map((row) => {
                    const attached = selected.some((item) => item.referenceId === row.id && item.revision === row.revision);
                    const usable = row.status === "ready" || row.status === "partial";
                    return <div className="reference-library-row" key={row.id}>
                        <div><ReferenceSourceLink projectId={projectId}
                                                  attachment={referenceAttachment(row)}/><small>{row.kind.toUpperCase()} · {(row.size / 1024).toFixed(0)} KB
                            · {REFERENCE_STATUS_LABELS[row.status]}{row.kind !== "image" && usable ? ` · ${row.coverage.characters.toLocaleString()} 字符` : ""}</small>{row.error &&
                            <p className="reference-error">{row.error}</p>}{row.warnings.map((warning, i) => <p
                            className="reference-warning" key={i}>{warning}</p>)}</div>
                        <div className="reference-row-actions">{(row.status === "failed" || row.status === "parsing") &&
                            <button type="button" disabled={!!busy} aria-label={`重新解析 ${row.filename}`}
                                    onClick={() => void retry(row)}><RotateCcw size={16}/></button>}
                            <button type="button" disabled={!usable || attached}
                                    onClick={() => onSelect(referenceAttachment(row))}
                                    aria-label={`${attached ? "已附加" : "附加"} ${row.filename}`}>{attached ?
                                <Check size={16}/> : <Plus size={16}/>}</button>
                            <button type="button" disabled={!!busy} onClick={() => setRemove(row)}
                                    aria-label={`移除资料 ${row.filename}`}><Trash2 size={15}/></button>
                        </div>
                    </div>;
                })}</div>
    </DialogContent></Dialog><AlertDialog open={!!remove} onOpenChange={(next) => {
        if (!next && !busy) setRemove(undefined);
    }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>从项目移除这份资料？</AlertDialogTitle><AlertDialogDescription>“{remove?.filename}”将无法用于新的消息和工具读取。历史消息及引用记录仍会保留。</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel
        disabled={!!busy}>取消</AlertDialogCancel><AlertDialogAction disabled={!!busy} onClick={(event) => {
        event.preventDefault();
        void removeSource();
    }}>移除资料</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>;
}

function ProjectImage({media, disabled, onSelect}: { media: MediaRecord; disabled: boolean; onSelect: () => void }) {
    const image = useBinaryPreview(media.blob);
    return <button type="button" className="reference-project-image" disabled={disabled || image.status !== "ready"} onClick={onSelect}
                   title={`附加 ${media.filename}`}>{image.status === "ready" ? <img src={image.url} onError={image.onError} alt={media.filename} loading="lazy"/> : <small>{binaryPreviewMessage(image)}</small>}<span>{media.filename}</span><small>附加图片</small>
    </button>;
}

import {useEffect, useRef, useState} from "react";
import {ArrowDown, ArrowUp, MoreHorizontal, Play, Plus, Trash2, Volume2} from "lucide-react";
import {db} from "@/db/database";
import {addAudioSegment, deleteAudioSegment, patchAudioSegment} from "@/db/audio";
import {appendAudioScript, editAudioScriptLines} from "@/lib/audio/scriptImport";
import type {AudioChapter, AudioProjectSnapshot, AudioSegment} from "@/domain/audio";
import {DraftConflictError} from "@/lib/draftConflict";
import {flushPendingDrafts, useDebouncedDraft} from "@/lib/debouncedDraft";
import {Button} from "@/components/ui/button";
import {Textarea} from "@/components/ui/textarea";
import {DraftStatus} from "@/components/ui/draft-status";
import {Popover, PopoverContent, PopoverTrigger} from "@/components/ui/popover";
import {Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle} from "@/components/ui/dialog";
import {useMedia} from "@/lib/media";
import {SourcePlayer} from "@/components/audioMusic/controls";
import type {AudioAction} from "./AudioInspector";

export function ScriptDocument({chapter, snapshot, selectedId, busy, action, onSelect, onInspect, onVoices}: {
    chapter: AudioChapter;
    snapshot: AudioProjectSnapshot;
    selectedId: string;
    busy: boolean;
    action: AudioAction;
    onSelect: (segment: AudioSegment) => void;
    onInspect: (segment: AudioSegment) => void;
    onVoices: (segment: AudioSegment) => void;
}) {
    const segments = snapshot.segments.filter((row) => row.chapterId === chapter.id);
    const [pasting, setPasting] = useState(false);
    const [pasted, setPasted] = useState("");
    const [focusRequest, setFocusRequest] = useState<{ id: string; atEnd?: boolean }>();
    useEffect(() => {
        if (!focusRequest) return;
        const row = segments.find((item) => item.id === focusRequest.id);
        const input = document.getElementById(`script-input-${focusRequest.id}`) as HTMLTextAreaElement | null;
        if (!row || !input) return;
        input.focus();
        const caret = focusRequest.atEnd ? input.value.length : 0;
        input.setSelectionRange(caret, caret);
        onSelect(row);
        setFocusRequest(undefined);
    }, [focusRequest, segments, onSelect]);

    async function add(text = "") {
        const segment = await addAudioSegment(chapter.projectId, {
            chapterId: chapter.id,
            order: Math.max(0, ...segments.map((row) => row.order)) + 1,
            text,
            notes: ""
        });
        onSelect(segment);
        setFocusRequest({id: segment.id});
    }

    return <div className="as-document">
        {!segments.length ? <div className="as-blank-document"><p>当前章节还没有脚本</p>
            <span>写下脚本，或者导入、录制已有声音。制作方式由你决定。</span>
            <div><Button disabled={busy} onClick={() => void action(() => add())}><Plus/>写下第一段</Button><Button
                variant="ghost" onClick={() => setPasting(true)}>粘贴完整稿件</Button></div>
        </div> : <div className="as-paragraphs">{segments.map((segment, index) => <ScriptParagraph key={segment.id}
                                                                                                   segment={segment}
                                                                                                   index={index}
                                                                                                   siblings={segments}
                                                                                                   snapshot={snapshot}
                                                                                                   selected={selectedId === segment.id}
                                                                                                   busy={busy}
                                                                                                   action={action}
                                                                                                   onSelect={() => onSelect(segment)}
                                                                                                   onInspect={() => onInspect(segment)}
                                                                                                   onVoices={() => onVoices(segment)}
                                                                                                   onFocusNew={(id, atEnd) => setFocusRequest({
                                                                                                       id,
                                                                                                       atEnd
                                                                                                   })}/>)}</div>}
        {segments.length > 0 && <footer className="as-document-footer"><Button size="sm" variant="ghost" disabled={busy}
                                                                               onClick={() => void action(() => add())}><Plus/>添加一行</Button><Button
            size="sm" variant="ghost" onClick={() => setPasting(true)}>粘贴稿件</Button><span>文字编辑自动保存</span>
        </footer>}
        <Dialog open={pasting}
                onOpenChange={setPasting}><DialogContent className="flex max-h-[calc(100dvh-32px)] flex-col overflow-hidden"><DialogHeader className="shrink-0"><DialogTitle>粘贴稿件</DialogTitle><DialogDescription>每个非空回车行作为一个编辑单位，追加到当前章节。已有内容会保留。</DialogDescription></DialogHeader><div className="min-h-0 overflow-y-auto pr-1"><Textarea
            value={pasted} onChange={(e) => setPasted(e.target.value)} rows={12} aria-label="完整稿件"
            placeholder="第一段台词…&#10;&#10;下一段台词…"/></div><DialogFooter className="shrink-0"><Button disabled={busy || !pasted.trim()}
                                                                    onClick={() => void action(async () => {
                                                                        const added = await appendAudioScript(chapter.projectId, chapter.id, pasted);
                                                                        const last = added.at(-1);
                                                                        setPasted("");
                                                                        setPasting(false);
                                                                        if (last) onSelect(last);
                                                                    })}>添加 {pasted.split(/\r?\n/).filter((part) => part.trim()).length} 行</Button></DialogFooter></DialogContent></Dialog>
    </div>;
}

function ScriptParagraph({
                             segment,
                             index,
                             siblings,
                             snapshot,
                             selected,
                             busy,
                             action,
                             onSelect,
                             onInspect,
                             onVoices,
                             onFocusNew
                         }: {
    segment: AudioSegment;
    index: number;
    siblings: AudioSegment[];
    snapshot: AudioProjectSnapshot;
    selected: boolean;
    busy: boolean;
    action: AudioAction;
    onSelect: () => void;
    onInspect: () => void;
    onVoices: () => void;
    onFocusNew: (id: string, atEnd?: boolean) => void;
}) {
    const [roleOpen, setRoleOpen] = useState(false);
    const [audition, setAudition] = useState(false);
    const textarea = useRef<HTMLTextAreaElement>(null);
    const speaker = snapshot.speakers.find((row) => row.id === segment.speakerId);
    const takes = snapshot.takes.filter((row) => row.segmentId === segment.id);
    const adopted = takes.find((take) => take.id === segment.selectedTakeId);
    const auditionTake = adopted ?? takes.at(-1);
    const preview = useMedia(audition && selected ? auditionTake?.mediaId : undefined);
    const {draft, setDraft, status, error, retry, useLatest} = useDebouncedDraft({
        scope: segment.projectId,
        draftKey: `${segment.id}:text`,
        initialValue: segment.text,
        persist: async (text, baseline) => {
            const current = await db.audioSegments.get(segment.id);
            if (!current || current.text !== baseline) throw new DraftConflictError();
            await patchAudioSegment(segment.projectId, current.id, current.revision, {text});
        }
    });
    useEffect(() => {
        const input = textarea.current;
        if (!input) return;
        const measure = () => {
            input.style.height = "auto";
            input.style.height = `${input.scrollHeight}px`;
        };
        measure();
        let width = input.getBoundingClientRect().width;
        const observer = new ResizeObserver((entries) => {
            const nextWidth = entries[0]?.contentRect.width;
            if (nextWidth === undefined || Math.abs(nextWidth - width) < 0.5) return;
            width = nextWidth;
            measure();
        });
        observer.observe(input);
        return () => observer.disconnect();
    }, [draft]);

    async function splitLine(start: number, end: number) {
        await flushPendingDrafts(segment.projectId);
        const rows = await editAudioScriptLines({
            projectId: segment.projectId,
            segmentId: segment.id,
            baseline: draft,
            start,
            end
        });
        if (rows[1]) onFocusNew(rows[1].id);
    }

    return <article id={`script-${segment.id}`} className="as-paragraph" data-selected={selected} onFocus={onSelect}>
        <div className="as-paragraph-gutter"><Popover open={roleOpen} onOpenChange={setRoleOpen}><PopoverTrigger
            asChild><Button variant="ghost" size="icon" className="as-role-button"
                            aria-label={`段落 ${index + 1} 选择说话人和音色`}><span
            className="as-voice-avatar">{speaker?.name.slice(0, 1) ??
            <MoreHorizontal size={14}/>}</span></Button></PopoverTrigger><PopoverContent align="start"
                                                                                         className="as-role-popover">
            <h3>这段由谁来讲述</h3>
            <div className="as-role-options"><Button variant={!speaker ? "secondary" : "ghost"}
                                                     className="justify-start" disabled={busy}
                                                     onClick={() => void action(async () => {
                                                         await patchAudioSegment(segment.projectId, segment.id, segment.revision, {speakerId: undefined});
                                                         setRoleOpen(false);
                                                     })}>MiMo 默认音色</Button>{snapshot.speakers.map((row) => <Button
                key={row.id} variant={row.id === speaker?.id ? "secondary" : "ghost"} className="justify-start"
                disabled={busy} onClick={() => void action(async () => {
                await patchAudioSegment(segment.projectId, segment.id, segment.revision, {speakerId: row.id});
                setRoleOpen(false);
            })}>{row.name}<span
                className="text-muted-foreground ml-auto text-xs">{row.mimo ? row.mimo.mode === "design" ? "设计音色" : row.mimo.mode === "clone" ? "克隆音色" : row.voice ?? "MiMo 默认" : row.voice ?? "alloy"}</span></Button>)}
            </div>
            <Button size="sm" variant="ghost" disabled={busy} onClick={() => {
                setRoleOpen(false);
                onVoices();
            }}><Plus/>创作 / 管理音色</Button>
            <div className="as-line-menu-actions"><Button size="sm" variant="ghost" onClick={() => {
                setRoleOpen(false);
                onInspect();
            }}><Volume2 size={13}/>声音与生成</Button>{auditionTake &&
                <Button size="sm" variant="ghost" onClick={() => {
                    setAudition(!audition);
                    setRoleOpen(false);
                }}><Play size={13}/>试听</Button>}<Button size="sm" variant="ghost" disabled={busy || index === 0}
                                                          onClick={() => void action(() => patchAudioSegment(segment.projectId, segment.id, segment.revision, {order: index > 1 ? (siblings[index - 2].order + siblings[index - 1].order) / 2 : siblings[0].order / 2}))}><ArrowUp/>上移</Button><Button
                size="sm" variant="ghost" disabled={busy || index === siblings.length - 1}
                onClick={() => void action(() => patchAudioSegment(segment.projectId, segment.id, segment.revision, {order: index + 2 < siblings.length ? (siblings[index + 1].order + siblings[index + 2].order) / 2 : siblings[index + 1].order + 1}))}><ArrowDown/>下移</Button><Button
                size="sm" variant="ghost" disabled={busy} onClick={() => void action(async () => {
                await flushPendingDrafts(segment.projectId);
                const current = await db.audioSegments.get(segment.id);
                if (current) await deleteAudioSegment(segment.projectId, segment.id, current.revision);
            })}><Trash2/>删除此行</Button></div>
        </PopoverContent></Popover></div>
        <div className="as-paragraph-main"><Textarea id={`script-input-${segment.id}`} ref={textarea}
                                                     className="as-script-input" aria-label={`第 ${index + 1} 行正文`}
                                                     value={draft} onChange={(event) => setDraft(event.target.value)}
                                                     onKeyDown={(event) => {
                                                         if (event.key === "Backspace" && !draft && event.currentTarget.selectionStart === 0 && event.currentTarget.selectionEnd === 0 && index > 0 && !event.nativeEvent.isComposing) {
                                                             event.preventDefault();
                                                             const previous = siblings[index - 1];
                                                             void action(async () => {
                                                                 await flushPendingDrafts(segment.projectId);
                                                                 const current = await db.audioSegments.get(segment.id);
                                                                 if (!current || current.text) throw new DraftConflictError();
                                                                 await deleteAudioSegment(segment.projectId, current.id, current.revision);
                                                                 onFocusNew(previous.id, true);
                                                             });
                                                             return;
                                                         }
                                                         if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
                                                             event.preventDefault();
                                                             const start = event.currentTarget.selectionStart;
                                                             const end = event.currentTarget.selectionEnd;
                                                             void action(() => splitLine(start, end));
                                                         }
                                                     }} onPaste={(event) => {
            const pasted = event.clipboardData.getData("text/plain");
            if (!/[\r\n]/.test(pasted)) return;
            event.preventDefault();
            const start = event.currentTarget.selectionStart;
            const end = event.currentTarget.selectionEnd;
            void action(async () => {
                await flushPendingDrafts(segment.projectId);
                const rows = await editAudioScriptLines({
                    projectId: segment.projectId,
                    segmentId: segment.id,
                    baseline: draft,
                    start,
                    end,
                    pasted
                });
                if (rows.length > 1) onFocusNew(rows.at(-1)!.id);
            });
        }} placeholder="写下正文…" rows={1}/>{status === "error" &&
            <DraftStatus status={status} error={error} onRetry={() => void retry()}
                         onUseLatest={useLatest}/>}{preview &&
            <div className="as-inline-audition"><SourcePlayer src={preview.url} onError={preview.onError} title={`第 ${index + 1} 行`} autoplay/>
            </div>}</div>
    </article>;
}

