const EMPTY_VALUE = "__workspace_no_selection__";

/** Keep one set of studio selection primitives across both workspaces. */
export function WorkspaceSelect({value, onValueChange, disabled, className, children, "aria-label": ariaLabel}: {
    value: string;
    onValueChange: (value: string) => void;
    disabled?: boolean;
    className?: string;
    children: ReactNode;
    "aria-label"?: string;
}) {
    return <Select value={value || EMPTY_VALUE}
                   onValueChange={(next) => onValueChange(next === EMPTY_VALUE ? "" : next)} disabled={disabled}>
        <SelectTrigger aria-label={ariaLabel} className={`aw-select ${className ?? ""}`}><SelectValue/></SelectTrigger>
        <SelectContent>{children}</SelectContent>
    </Select>;
}

export function SelectOption({value, children}: { value: string; children: ReactNode }) {
    return <SelectItem value={value || EMPTY_VALUE}>{children}</SelectItem>;
}

/** Adapt scalar workspace values to the shared shadcn slider. */
export function WorkspaceSlider({
                                    value,
                                    defaultValue,
                                    min = 0,
                                    max = 1,
                                    step = 0.01,
                                    onChange,
                                    onCommit,
                                    label,
                                    disabled,
                                    className
                                }: {
    value?: number;
    defaultValue?: number;
    min?: number;
    max?: number;
    step?: number;
    onChange?: (value: number) => void;
    onCommit?: (value: number) => void;
    label: string;
    disabled?: boolean;
    className?: string;
}) {
    return <Slider
        className={`aw-slider ${className ?? ""}`}
        value={value === undefined ? undefined : [value]}
        defaultValue={defaultValue === undefined ? [min] : [defaultValue]}
        min={min} max={max} step={step}
        onValueChange={onChange ? ([next]) => onChange(next) : undefined}
        onValueCommit={onCommit ? ([next]) => onCommit(next) : undefined}
        aria-label={label} disabled={disabled}
    />;
}

export type AudioPlaybackActions = {
    onPrevious?: () => void;
    onNext?: () => void;
    onEnded?: () => void;
    onError?: () => void;
    onPlayingChange?: (playing: boolean) => void;
    toggleRequest?: number;
};

export function SourcePlayer({
                                 src,
                                 title,
                                 autoplay = false,
                                 onPrevious,
                                 onNext,
                                 onEnded,
                                 onError,
                                 onPlayingChange,
                                 toggleRequest
                             }: { src: string; title: string; autoplay?: boolean } & AudioPlaybackActions) {
    const audio = useRef<HTMLAudioElement>(null);
    const currentSource = useRef(src);
    currentSource.current = src;
    const [playing, setPlaying] = useState(false);
    const [position, setPosition] = useState(0);
    const [duration, setDuration] = useState(0);
    const [volume, setVolume] = useState(1);
    const [error, setError] = useState("");
    useEffect(() => {
        const stop = (event: Event) => {
            if (event.target !== audio.current) audio.current?.pause();
        };
        document.addEventListener("play", stop, true);
        const element = audio.current;
        return () => {
            document.removeEventListener("play", stop, true);
            element?.pause();
        };
    }, []);
    useEffect(() => {
        setPosition(0);
        setDuration(0);
        setPlaying(false);
        setError("");
    }, [src]);
    const lastToggle = useRef(toggleRequest);
    useEffect(() => {
        if (toggleRequest === lastToggle.current) return;
        lastToggle.current = toggleRequest;
        const element = audio.current;
        if (!element) return;
        if (!element.paused) element.pause();
        else void element.play().catch(() => setError("播放被浏览器阻止，请再次点击播放。"));
    }, [toggleRequest]);
    const format = (seconds: number) => `${Math.floor(seconds / 60)}:${String(Math.floor(seconds % 60)).padStart(2, "0")}`;
    return <div className="aw-custom-player">
        <audio ref={audio} src={src} autoPlay={autoplay} preload="metadata"
               onLoadedMetadata={(e) => setDuration(Number.isFinite(e.currentTarget.duration) ? e.currentTarget.duration : 0)}
               onDurationChange={(e) => setDuration(Number.isFinite(e.currentTarget.duration) ? e.currentTarget.duration : 0)}
               onTimeUpdate={(e) => setPosition(e.currentTarget.currentTime)} onPlay={() => {
            setPlaying(true);
            onPlayingChange?.(true);
            document.dispatchEvent(new CustomEvent("audio-workspace-audition"));
        }} onPause={() => {
            setPlaying(false);
            onPlayingChange?.(false);
        }} onEnded={() => {
            setPlaying(false);
            onPlayingChange?.(false);
            onEnded?.();
        }} onError={() => {
            if (currentSource.current !== src) return;
            setError("此音频无法播放，请检查文件格式或重新导入。");
            onError?.();
        }}/>
        {(onPrevious || onNext) && <Button size="icon-sm" variant="ghost" aria-label="上一首" disabled={!onPrevious}
                                           onClick={onPrevious}><SkipBack size={16}/></Button>}
        <Button size="icon-sm" variant="ghost" aria-label={`${playing ? "暂停" : "播放"} ${title}`} onClick={() => {
            if (playing) audio.current?.pause(); else void audio.current?.play().catch(() => setError("播放被浏览器阻止，请再次点击播放。"));
        }}>{playing ? <Pause size={16}/> : <Play size={16}/>}</Button>
        {(onPrevious || onNext) &&
            <Button size="icon-sm" variant="ghost" aria-label="下一首" disabled={!onNext} onClick={onNext}><SkipForward
                size={16}/></Button>}
        <span className="aw-time">{format(position)}</span>
        <WorkspaceSlider label={`${title} 播放进度`} className="aw-playback-slider" value={Math.min(position, duration)}
                         max={duration || 1} disabled={!duration} step={0.01} onChange={(seconds) => {
            if (audio.current) audio.current.currentTime = seconds;
            setPosition(seconds);
        }}/>
        <span className="aw-time aw-muted">{format(duration)}</span>
        <Button size="icon-sm" variant="ghost" aria-label={volume ? "静音试听" : "恢复试听音量"} onClick={() => {
            const next = volume ? 0 : 1;
            if (audio.current) audio.current.volume = next;
            setVolume(next);
        }}>{volume ? <Volume2 size={15}/> : <VolumeX size={15}/>}</Button>
        <WorkspaceSlider label="试听音量" className="aw-volume-slider" value={volume} onChange={(next) => {
            if (audio.current) audio.current.volume = next;
            setVolume(next);
        }}/>
        {error && <span role="alert" className="aw-error">{error}</span>}
    </div>;
}

